    ext_time: n.ext_time || '',
    duration: n.duration || '',
    created: n.created || '',
    thumb: n.thumb || ('https://grok.com/imagine/post/' + String(n.uuid).toLowerCase() + '/image'),
    video_url: n.video_url || null,
    is_generated: !!n.is_generated,
    index_method: n.index_method || '',
