      ok: true,
      uptime_s: Math.round((Date.now() - _perf.since) / 1000),
      galleryOpen: galleryIsOpen(),
      items: _memGallery ? _memGallery.order.length : null,
      flushes: _perf.flushes,
      flushAvgMs: _perf.flushes ? +(_perf.flushMs / _perf.flushes).toFixed(1) : 0,
      flushMaxMs: +_perf.flushMaxMs.toFixed(1),
      shardsWritten: _perf.shardsWritten,
      deltasSent: _perf.deltas,
      enrichRuns: _perf.enrich,
